class BytesIOCopy:
    """A real, file-descriptor backed buffer that copies everything
    written to it to another stream.

    Unlike a plain ``io.BytesIO``, this is backed by a real temporary
    file, so it has a working ``fileno()``. This allows code under test
    to pass ``sys.stdout``/``sys.stderr`` (wrapping this object) to APIs
    such as :func:`subprocess.run` that require a real file descriptor.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3.2
        Backed by a real temporary file instead of ``io.BytesIO`` so
        that ``fileno()`` works.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file: t.BinaryIO = t.cast("t.BinaryIO", tempfile.TemporaryFile())
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def fileno(self) -> int:
        return self._file.fileno()


